#include "dfre/mission_type_mark.hpp"
#include <cassert>
#include <cstring>
int main(){using namespace dfre;MissionTickState state;AiTypeSlotTable types;types.bytes.fill(0xa5);auto bindings=mission_type_count_bindings(state,types);mission_type_mark(bindings,0);mission_type_mark(bindings,63);mission_type_mark(bindings,0x4000000);for(std::size_t off=0;off<types.bytes.size();++off){const auto field=off==0x24||off==63*0x40+0x24;if(field)assert(types.bytes[off]==2);else if((off>0x24&&off<0x28)||(off>63*0x40+0x24&&off<63*0x40+0x28))assert(types.bytes[off]==0);else assert(types.bytes[off]==0xa5);}const auto old=types.bytes;bool failed=false;try{mission_type_mark(bindings,64);}catch(const MissionTickError&){failed=true;}assert(failed&&old==types.bytes);failed=false;try{mission_type_mark({},1);}catch(const MissionTickError&){failed=true;}assert(failed);unsigned writes=0;bindings.write=[&](auto at,auto width,auto value){++writes;assert(at==0x7926a4&&width==4&&value==2);};mission_type_mark(bindings,0xffffffc0);assert(writes==1);}
